// Recorded fixed-time vs FlowState results: held-out SUMO evaluations from the RL branch,
// generated by frontend/scripts/extract_controller_results.py. Numbers are copied, never recomputed.
import raw from '../data/controllerResults.json'

export type ControllerId = 'fixed_time' | 'queue_heuristic' | 'rl_ppo'
export type DemandLevel = 'standard' | 'stress'
export type MetricKey =
  | 'mean_wait_s'
  | 'mean_travel_s'
  | 'p95_travel_s'
  | 'throughput_vph'
  | 'completed_fraction'
  | 'queue_mean_veh'
  | 'queue_max_veh'
  | 'spillback_pct'
  | 'teleports'
  | 'collisions'
  | 'emergency_mean_stopped_s'

export interface VsBaseline {
  diff: number
  ci95: [number, number]
  pct: number | null
  p: number | null
  better: number
  worse: number
  paired: number
}

export interface MetricStats {
  mean: number
  std: number
  min: number
  max: number
  vs?: VsBaseline
}

export interface ControllerSummary {
  n: number
  metrics: Partial<Record<MetricKey, MetricStats>>
}

export type SummaryGroup = Partial<Record<ControllerId, ControllerSummary>>

export interface EpisodeRow {
  c: ControllerId
  s: string
  seed: number
  wait: number
  travel: number
  queueMax: number
  teleports: number
}

export interface DemandResults {
  intensity: number
  seeds: number[]
  episodes: number
  wallSeconds: number | null
  overall: SummaryGroup
  perScenario: Record<string, SummaryGroup>
  runs: EpisodeRow[]
}

export interface ControllerResults {
  source: { ref: string; commit: string; files: string[] }
  network: { id: string; description: string }
  baseline: ControllerId
  flowstate: ControllerId
  controllers: Record<ControllerId, { title: string; detail: string; status: 'baseline' | 'verified' | 'experimental' }>
  safety: { minGreen: number; yellow: number; allRed: number; maxGreen: number; decision: number }
  scenarios: { id: string; title: string; description: string; heldOut: boolean }[]
  demand: Record<DemandLevel, DemandResults>
}

export const results = raw as unknown as ControllerResults

export interface MetricDef {
  key: MetricKey
  label: string
  unit: string
  better: 'lower' | 'higher'
  digits: number
  note: string
  /** displayed value = stored value * scale */
  scale?: number
}

export const METRICS: Record<MetricKey, MetricDef> = {
  mean_wait_s: { key: 'mean_wait_s', label: 'Mean wait', unit: 's', better: 'lower', digits: 1, note: 'Seconds each vehicle stood still, including delay before it could enter' },
  mean_travel_s: { key: 'mean_travel_s', label: 'Mean travel time', unit: 's', better: 'lower', digits: 1, note: 'Arrival minus scheduled departure' },
  p95_travel_s: { key: 'p95_travel_s', label: '95th-percentile travel time', unit: 's', better: 'lower', digits: 0, note: 'The slowest 5% of trips' },
  throughput_vph: { key: 'throughput_vph', label: 'Throughput', unit: 'veh/h', better: 'higher', digits: 0, note: 'Vehicles arriving within the demand window' },
  completed_fraction: { key: 'completed_fraction', label: 'Trips completed', unit: '%', better: 'higher', digits: 1, note: 'Completed / scheduled after the drain period', scale: 100 },
  queue_mean_veh: { key: 'queue_mean_veh', label: 'Mean queue per approach', unit: 'veh', better: 'lower', digits: 1, note: 'Stopped vehicles per approach, averaged over time' },
  queue_max_veh: { key: 'queue_max_veh', label: 'Peak queue', unit: 'veh', better: 'lower', digits: 0, note: 'Most stopped vehicles on all approaches at once' },
  spillback_pct: { key: 'spillback_pct', label: 'Spillback', unit: '%', better: 'lower', digits: 1, note: 'Share of time a queue covered half a block or more' },
  teleports: { key: 'teleports', label: 'Gridlock teleports', unit: '', better: 'lower', digits: 1, note: 'Vehicles SUMO removed after being stuck; per run' },
  collisions: { key: 'collisions', label: 'Collisions', unit: '', better: 'lower', digits: 1, note: 'Distinct collision pairs; per run' },
  emergency_mean_stopped_s: { key: 'emergency_mean_stopped_s', label: 'Emergency vehicle stopped time', unit: 's', better: 'lower', digits: 1, note: 'Seconds an emergency vehicle stood still' },
}

export const scale = (m: MetricDef, v: number | null | undefined) => (v == null ? null : v * (m.scale ?? 1))

export type Verdict = 'better' | 'worse' | 'unclear'

export const MIN_PAIRED = 3

/** Clear only when the paired 95% interval of the difference excludes zero, over enough paired runs to have one. */
export function verdict(m: MetricDef, vs: VsBaseline | undefined): Verdict {
  if (!vs || vs.paired < MIN_PAIRED) return 'unclear'
  const [lo, hi] = vs.ci95
  if (lo <= 0 && hi >= 0) return 'unclear'
  const lower = hi < 0
  return (m.better === 'lower') === lower ? 'better' : 'worse'
}

export const VERDICT_LABEL: Record<Verdict, string> = { better: 'Clear improvement', worse: 'Clearly worse', unclear: 'No clear difference' }

/** Change expressed so that positive always means "FlowState is better". */
export function improvementPct(m: MetricDef, base: number, vs: VsBaseline): { mid: number; lo: number; hi: number } | null {
  if (!base) return null
  const sign = m.better === 'lower' ? -1 : 1
  const a = (sign * vs.ci95[0] * 100) / base
  const b = (sign * vs.ci95[1] * 100) / base
  return { mid: (sign * vs.diff * 100) / base, lo: Math.min(a, b), hi: Math.max(a, b) }
}

// ---- live comparisons: /api/rl (docs/RL_INTEGRATION_CONTRACT.md on task/rl-signal-control) ----

export interface RlInfo {
  scenarios: { id: string; title: string; description: string; held_out: boolean }[]
  intensity: { standard: number; stress: number; range: [number, number] }
  controllers: { id: string; title: string; available: boolean; status: string; note?: string }[]
  default_controller: string
}

export interface RlCompareRequest {
  controllers: string[]
  scenarios: string[]
  seeds: number[]
  intensity: number
  baseline: string
  include_series: boolean
}

interface RawStats {
  mean: number
  std: number
  min: number
  max: number
  vs_baseline?: { mean_diff: number; ci95: [number, number]; pct_change: number | null; wilcoxon_p: number | null; better_in: number; worse_in: number; paired: number }
}
type RawGroup = Record<string, { n: number; metrics: Record<string, RawStats> }>

export interface RlResult {
  request: RlCompareRequest
  fallbacks: { requested: string; used: string; reason: string }[]
  summary: { baseline: string; overall: RawGroup; per_scenario: Record<string, RawGroup> }
  episodes: { requested_controller: string; scenario: string; seed: number; mean_wait_s: number; mean_travel_s: number; queue_max_veh: number; teleports: number }[]
  wall_seconds: number
  caveat: string
}

export interface RlJob {
  id: string
  status: 'queued' | 'running' | 'done' | 'failed'
  progress: { done: number; total: number }
  result: RlResult | null
  error: string | null
}

function group(raw: RawGroup): SummaryGroup {
  const out: SummaryGroup = {}
  for (const [c, v] of Object.entries(raw)) {
    const metrics: ControllerSummary['metrics'] = {}
    for (const [k, m] of Object.entries(v.metrics)) {
      const vs = m.vs_baseline
      metrics[k as MetricKey] = {
        mean: m.mean,
        std: m.std,
        min: m.min,
        max: m.max,
        vs: vs && { diff: vs.mean_diff, ci95: vs.ci95, pct: vs.pct_change, p: vs.wilcoxon_p, better: vs.better_in, worse: vs.worse_in, paired: vs.paired },
      }
    }
    out[c as ControllerId] = { n: v.n, metrics }
  }
  return out
}

/** A finished live comparison in the shape the recorded results use. */
export function fromLive(r: RlResult): DemandResults {
  return {
    intensity: r.request.intensity,
    seeds: r.request.seeds,
    episodes: r.episodes.length,
    wallSeconds: r.wall_seconds,
    overall: group(r.summary.overall),
    perScenario: Object.fromEntries(Object.entries(r.summary.per_scenario).map(([s, g]) => [s, group(g)])),
    runs: r.episodes.map((e) => ({
      c: e.requested_controller as ControllerId,
      s: e.scenario,
      seed: e.seed,
      wait: e.mean_wait_s,
      travel: e.mean_travel_s,
      queueMax: e.queue_max_veh,
      teleports: e.teleports,
    })),
  }
}

/** Paired runs (same scenario + seed => identical vehicles) for two controllers. */
export function pairs(d: DemandResults, a: ControllerId, b: ControllerId) {
  const key = (r: EpisodeRow) => `${r.s}/${r.seed}`
  const bs = new Map(d.runs.filter((r) => r.c === b).map((r) => [key(r), r]))
  return d.runs.filter((r) => r.c === a && bs.has(key(r))).map((r) => ({ s: r.s, seed: r.seed, a: r, b: bs.get(key(r))! }))
}
